use crate::bank::Bank; use crate::modes::Mode; use directories::ProjectDirs; use serde::{Deserialize, Serialize}; use std::{fs, io, path::PathBuf, time::{SystemTime, UNIX_EPOCH}};
#[derive(Clone, Debug, Serialize, Deserialize)] pub struct Stats { pub hands: u64, pub wins: u64, pub biggest_win: i64, pub biggest_loss: i64, pub total_profit: i64, pub streak: i64, pub best_streak: i64 }
impl Default for Stats { fn default() -> Self { Self { hands: 0, wins: 0, biggest_win: 0, biggest_loss: 0, total_profit: 0, streak: 0, best_streak: 0 } } }
#[derive(Clone, Debug, Serialize, Deserialize)] pub struct Player { pub chips: u64, pub bank: Bank, pub stats: Stats, pub xp: u64, pub broken_bank: bool, pub house_bankroll: u64, #[serde(default)] pub achievements: Vec<String>, pub dev_mode: bool, pub last_bonus: u64, pub last_bailout: u64 }
impl Default for Player { fn default() -> Self { Self { chips: 1000, bank: Bank::default(), stats: Stats::default(), xp: 0, broken_bank: false, house_bankroll: 100_000, achievements: Vec::new(), dev_mode: false, last_bonus: 0, last_bailout: 0 } } }
impl Player { pub fn level(&self) -> u32 { (self.xp / 100 + 1) as u32 } pub fn mode_unlocked(&self, mode: Mode) -> bool { mode.unlocked(self.level(), self.broken_bank) } pub fn record(&mut self, profit: i64) { self.stats.hands += 1; self.stats.total_profit += profit; if profit > 0 { self.stats.wins += 1; self.stats.streak += 1; self.stats.best_streak = self.stats.best_streak.max(self.stats.streak); self.stats.biggest_win = self.stats.biggest_win.max(profit); } else { self.stats.streak = 0; self.stats.biggest_loss = self.stats.biggest_loss.min(profit); } self.xp += 10; } pub fn unlock(&mut self, name: &str) { if !self.achievements.iter().any(|a| a == name) { self.achievements.push(name.to_string()); } } pub fn daily(&mut self) { let now = epoch(); if self.bank.last_interest_day <= 0 { self.bank.last_interest_day = now as i64; } let days = now.saturating_sub(self.bank.last_interest_day.max(0) as u64) / 86_400; if days > 0 { self.bank.interest(days); self.bank.last_interest_day += (days as i64) * 86_400; } if now.saturating_sub(self.last_bonus) >= 86_400 { self.chips += 250; self.last_bonus = now; } if self.chips == 0 && now.saturating_sub(self.last_bailout) >= 86_400 { self.chips = 500; self.last_bailout = now; } } pub fn settle_house(&mut self, profit: i64) -> bool { if profit > 0 { self.house_bankroll = self.house_bankroll.saturating_sub(profit as u64); if self.house_bankroll == 0 { self.broken_bank = true; self.house_bankroll = 100_000; return true; } } else if profit < 0 { self.house_bankroll = self.house_bankroll.saturating_add((-profit) as u64); } false } }
fn epoch() -> u64 { SystemTime::now().duration_since(UNIX_EPOCH).map_or(0, |d| d.as_secs()) }
pub fn path() -> io::Result<PathBuf> { ProjectDirs::from("", "", "blackjack-tui").map(|p| p.data_dir().join("save.json")).ok_or_else(|| io::Error::other("could not determine data directory")) }
pub fn load() -> Player { let p = match path() { Ok(p) => p, Err(_) => return Player::default() }; match fs::read_to_string(&p).ok().and_then(|s| serde_json::from_str(&s).ok()) { Some(player) => player, None => { if p.exists() { let _ = fs::rename(&p, p.with_extension("json.corrupt")); } Player::default() } } }
pub fn save(player: &Player) -> io::Result<()> { let p = path()?; if let Some(parent) = p.parent() { fs::create_dir_all(parent)?; } let temp = p.with_extension("json.tmp"); fs::write(&temp, serde_json::to_string_pretty(player).map_err(io::Error::other)?)?; fs::rename(temp, p) }
#[cfg(test)] mod tests { use super::*; #[test] fn broke_bailout() { let mut p = Player::default(); p.chips = 0; p.daily(); assert_eq!(p.chips, 250); } #[test] fn fresh_daily_does_not_apply_historical_interest() { let mut p = Player::default(); p.bank.savings = 1_000; p.daily(); assert_eq!(p.bank.savings, 1_000); } #[test] fn old_bank_json_defaults_interest_cursor() { let bank: Bank = serde_json::from_str(r#"{"savings":100,"loan":0}"#).expect("legacy bank JSON"); assert_eq!(bank.last_interest_day, 0); } }
